const SYSTEM_PROMPT = "You are a support triage assistant for Kesar & Co., an Indian D2C Ayurvedic skincare brand that sells on Shopify.\r\n\r\nRead the customer email and return a JSON object with these fields:\r\n\r\n- intent: the customer's main need. One of:\r\n  - order_status: asking where an order is, or when it will arrive\r\n  - product_query: questions about products, ingredients, shipping, COD or other policies\r\n  - return_refund: wants to return something, get a refund or replacement, or reports a damaged, wrong or missing item\r\n  - complaint: unhappy with the service or experience, or angry\r\n  - other: spam, partnership or press enquiries, invoices, thank-you notes, anything else\r\n- secondary_intent: a second need in the same email, using the same list, or null\r\n- order_id: the order number exactly as KC-#### if the email mentions one, otherwise null. Do not guess.\r\n- sentiment: positive, neutral, negative or angry\r\n- language: en (English), hi (Hindi in Devanagari) or hinglish (Hindi written in Latin letters mixed with English)\r\n- confidence: a number from 0 to 1 for how sure you are about the intent\r\n- summary: one line for the support team, in English, under 200 characters\r\n\r\nReturn only the JSON object.";
const POLICY = {"scenario_today":"2026-11-20","return_window_days":7,"damage_report_window_hours":48,"free_shipping_min_inr":999,"shipping_fee_inr":79,"cod_limit_inr":5000,"cod_fee_inr":49,"confidence_threshold":0.75,"high_value_inr":3000,"delivery_days_after_dispatch":{"metro":"2-4","rest_of_india":"4-6","north_east_and_remote":"6-8"},"dispatch_business_days":"1-2","follow_up_business_hours":24};

// Node: "Prepare email"  (n8n Code node, run once for each item)
//
// Takes the webhook payload (one email, exactly as in data/test_emails.json)
// and builds the request we send to Gemini.
//
// SYSTEM_PROMPT and POLICY are added above this code by scripts/build_workflow.js,
// from prompts/classify_v1.md and config/policy.json. Edit those files, not the
// workflow JSON.

// Model history on 2026-11-24 (see docs/BUILD_LOG.md):
//   gemini-2.5-flash      -> 404, no longer available to new users
//   gemini-3.8-flash      -> 503, high demand on the free tier
//   gemini-flash-latest   -> 503, same
//   gemini-flash-lite-latest -> works (resolved to gemini-3.5-flash-lite)
// "-latest" aliases avoid 404s when Google renames models, but they can change
// under us. The exact model used is stored in every Audit Log row ("model").
const MODEL = 'gemini-flash-lite-latest';
const PROMPT_VERSION = 'v1';

const email = $json.body || {};

// Basic shape check. A broken payload should be logged, not crash the flow.
const missing = [];
if (!email.id) missing.push('id');
if (!email.from || !email.from.email) missing.push('from.email');
if (!email.body) missing.push('body');

// The model only sees the text of the email.
const userText =
  'From: ' + (email.from && email.from.name || '') + ' <' + (email.from && email.from.email || '') + '>\n' +
  'Subject: ' + (email.subject || '') + '\n' +
  'Attachments: ' + ((email.attachments || []).join(', ') || 'none') + '\n\n' +
  (email.body || '');

// Smaller schema for Gemini. Gemini does not accept "pattern", "maxLength" or
// type arrays, so those rules are checked in the next node instead.
const intents = ['order_status', 'product_query', 'return_refund', 'complaint', 'other'];
const responseSchema = {
  type: 'OBJECT',
  properties: {
    intent: { type: 'STRING', enum: intents },
    secondary_intent: { type: 'STRING', enum: intents, nullable: true },
    order_id: { type: 'STRING', nullable: true },
    sentiment: { type: 'STRING', enum: ['positive', 'neutral', 'negative', 'angry'] },
    language: { type: 'STRING', enum: ['en', 'hi', 'hinglish'] },
    confidence: { type: 'NUMBER' },
    summary: { type: 'STRING' }
  },
  required: ['intent', 'secondary_intent', 'order_id', 'sentiment', 'language', 'confidence', 'summary']
};

return {
  json: {
    email,
    missing_fields: missing,
    model: MODEL,
    prompt_version: PROMPT_VERSION,
    started_at: Date.now(),
    gemini_request: {
      systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
      contents: [{ role: 'user', parts: [{ text: userText }] }],
      generationConfig: {
        temperature: 0,
        responseMimeType: 'application/json',
        responseSchema
      }
    }
  }
};

const POLICY = {"scenario_today":"2026-11-20","return_window_days":7,"damage_report_window_hours":48,"free_shipping_min_inr":999,"shipping_fee_inr":79,"cod_limit_inr":5000,"cod_fee_inr":49,"confidence_threshold":0.75,"high_value_inr":3000,"delivery_days_after_dispatch":{"metro":"2-4","rest_of_india":"4-6","north_east_and_remote":"6-8"},"dispatch_business_days":"1-2","follow_up_business_hours":24};

// Node: "Validate classification"  (n8n Code node, run once for each item)
//
// Checks the model's answer against schemas/llm_output.schema.json and builds
// the Audit Log row. It never throws: if anything is wrong the email falls back
// to intent "other" with needs_human = TRUE, and the reason goes in "error".
//
// POLICY is added above this code by scripts/build_workflow.js (config/policy.json).

const INTENTS = ['order_status', 'product_query', 'return_refund', 'complaint', 'other'];
const SENTIMENTS = ['positive', 'neutral', 'negative', 'angry'];
const LANGUAGES = ['en', 'hi', 'hinglish'];

const prep = $('Prepare email').item.json;
const email = prep.email || {};
const resp = $input.item.json;
const usage = resp.usageMetadata || {};

// Returns a list of problems. An empty list means the output is valid.
function check(o) {
  const p = [];
  if (typeof o !== 'object' || o === null || Array.isArray(o)) return ['not a JSON object'];
  for (const k of ['intent', 'secondary_intent', 'order_id', 'sentiment', 'language', 'confidence', 'summary']) {
    if (!(k in o)) p.push('missing ' + k);
  }
  if (!INTENTS.includes(o.intent)) p.push('bad intent');
  if (o.secondary_intent !== null && !INTENTS.includes(o.secondary_intent)) p.push('bad secondary_intent');
  if (o.order_id !== null && !/^KC-[0-9]{4}$/.test(String(o.order_id))) p.push('bad order_id');
  if (!SENTIMENTS.includes(o.sentiment)) p.push('bad sentiment');
  if (!LANGUAGES.includes(o.language)) p.push('bad language');
  if (typeof o.confidence !== 'number' || o.confidence < 0 || o.confidence > 1) p.push('bad confidence');
  if (typeof o.summary !== 'string') p.push('bad summary');
  else if (o.summary.length > 200) p.push('summary over 200 chars');
  return p;
}

let result = null;
let error = '';
let validFirstTry = false;

try {
  if (prep.missing_fields && prep.missing_fields.length) {
    throw new Error('payload missing: ' + prep.missing_fields.join(', '));
  }
  if (resp.error) {
    throw new Error('LLM call failed: ' + String(resp.error.message || JSON.stringify(resp.error)).slice(0, 200));
  }
  const text = resp.candidates && resp.candidates[0] && resp.candidates[0].content &&
    resp.candidates[0].content.parts && resp.candidates[0].content.parts[0].text;
  if (!text) throw new Error('empty model response');

  const parsed = JSON.parse(text);
  const problems = check(parsed);
  validFirstTry = problems.length === 0;

  // One cheap repair we can do safely: cut a too-long summary.
  if (problems.length === 1 && problems[0] === 'summary over 200 chars') {
    parsed.summary = parsed.summary.slice(0, 197) + '...';
    error = 'repaired: summary shortened';
  } else if (problems.length) {
    throw new Error('invalid output: ' + problems.join('; '));
  }
  result = parsed;
} catch (e) {
  error = String(e.message || e).slice(0, 300);
}

const fallback = result === null;
if (fallback) {
  result = {
    intent: 'other', secondary_intent: null, order_id: null, sentiment: 'neutral',
    language: 'en', confidence: 0, summary: 'Classification failed, needs manual review.'
  };
}

const needsHuman = fallback || result.confidence < POLICY.confidence_threshold;
const latency = Date.now() - (prep.started_at || Date.now());

const row = {
  email_id: email.id || '',
  received_at: email.received_at || '',
  from_email: (email.from && email.from.email) || '',
  intent: result.intent,
  secondary_intent: result.secondary_intent === null ? '' : result.secondary_intent,
  order_id: result.order_id === null ? '' : result.order_id,
  language: result.language,
  sentiment: result.sentiment,
  confidence: result.confidence,
  order_found: '',
  action_taken: fallback ? 'fallback_needs_human' : 'classified_only',
  needs_human: needsHuman ? 'TRUE' : 'FALSE',
  ticket_id: '',
  reply_draft: '',
  prompt_version: prep.prompt_version,
  processed_at: new Date().toISOString(),
  error: error,
  notes: result.summary,
  model: prep.model,
  tokens_in: usage.promptTokenCount || '',
  tokens_out: usage.candidatesTokenCount || '',
  cost_usd: '',
  latency_ms: latency,
  guard_flags: '',
  facts_json: '',
  trace_json: JSON.stringify({
    steps: [{ name: 'classify', model: prep.model, ms: latency, valid_first_try: validFirstTry,
              tokens_in: usage.promptTokenCount || 0, tokens_out: usage.candidatesTokenCount || 0 }]
  })
};

return { json: { row } };

// Node: "Build agent input"  (n8n Code node, run once for each item)  [v1]
//
// v1 hands the agent the raw email plus the classification. Nothing else:
// no decision, no facts, no rules. The agent works it all out itself.

const email = $('Prepare email').first().json.email || {};
const row = $input.item.json.row;

const text = [
  'From: ' + ((email.from && email.from.name) || '') + ' <' + ((email.from && email.from.email) || '') + '>',
  'Subject: ' + (email.subject || ''),
  'Attachments: ' + ((email.attachments || []).join(', ') || 'none'),
  '',
  email.body || '',
  '',
  '(Automatic classification: intent ' + row.intent + ', order ' + (row.order_id || 'none') + ', sentiment ' + row.sentiment + ', language ' + row.language + ')'
].join('\n');

return { json: { agent_input: text } };

