// Node: "Decide"  (n8n Code node, run once for each item)  [v1]
//
// Reads the agent's answer and applies the few v1 rules:
//   reply        : the agent's text, or nothing when it said NO_REPLY
//   ticket       : return_refund or complaint WITH an order number found by the classifier
//   needs_human  : the classifier failed, or its confidence is below the threshold
// There is no eligibility check, no output guard and no privacy check in v1.
//
// POLICY is added above this code by scripts/build_workflow_v1.js.
// AGENT_PROMPT_CHARS is added the same way.

const row = $('Validate classification').first().json.row;
const out = $input.item.json;
const steps = Array.isArray(out.intermediateSteps) ? out.intermediateSteps : [];

let reply = String(out.output === undefined ? '' : out.output).replace(/^```\w*\s*/, '').replace(/\s*```\s*$/, '').trim();
const agentFailed = out.output === undefined;
if (/^NO_REPLY\b/i.test(reply)) reply = '';

const fallback = row.action_taken === 'fallback_needs_human';
const confidence = Number(row.confidence);
const lowConf = !fallback && confidence < POLICY.confidence_threshold;
const reasons = [];
if (fallback) reasons.push('classification_failed');
if (lowConf) reasons.push('low_confidence');
if (agentFailed) reasons.push('agent_failed');

const getOrderCalls = steps.filter((s) => s.action && String(s.action.tool).indexOf('get_order') === 0);
const orderFound = getOrderCalls.some((s) => String(s.observation || '').indexOf('"order_id"') !== -1);

const ticketNeeded = !fallback && ['return_refund', 'complaint'].indexOf(row.intent) !== -1 && !!row.order_id;

const toolChars = steps.reduce((n, s) => n + String(s.observation || '').length, 0);
const agentIn = Math.ceil((AGENT_PROMPT_CHARS + String($('Build agent input').first().json.agent_input).length + toolChars) / 4);
const agentOut = Math.ceil(String(out.output || '').length / 4);

return {
  json: {
    row, reply, ticket_needed: ticketNeeded, needs_human: reasons.length > 0, reasons,
    action: fallback ? 'fallback_needs_human' : (agentFailed ? 'agent_failed' : (reply ? 'reply_drafted' : 'no_reply')),
    order_found: getOrderCalls.length ? orderFound : null,
    tools_used: steps.map((s) => (s.action && s.action.tool) || 'unknown'),
    tokens_agent_in_est: agentIn, tokens_agent_out_est: agentOut
  }
};

// Node: "Plan ticket"  (n8n Code node, run once for ALL items)  [v1]
//
// One open ticket per order: update it if there is one, otherwise create a new one.
// Same idea as v2, with simpler rules: priority is High for an angry customer, else Medium,
// and an update never changes the priority.
//
// Input : every row of the "Tickets v1" tab
// Output: one ticket row for "Write ticket" to upsert on ticket_id

const d = $('Decide').first().json;
const row = d.row;
const email = $('Prepare email').first().json.email;

const rows = $input.all().map((i) => i.json).filter((r) => r && r.ticket_id);
const open = rows.find((r) => r.order_id === row.order_id && String(r.status).trim().toLowerCase() !== 'closed');
const note = '[' + email.id + ' ' + email.received_at + '] ' + row.notes;

let mode;
let ticket;
if (open) {
  const ids = String(open.email_ids || '').split(',').map((s) => s.trim()).filter(Boolean);
  const already = ids.includes(email.id);
  mode = already ? 'noop' : 'update';
  ticket = Object.assign({}, open, already ? {} : {
    updated_at: email.received_at, email_ids: ids.concat(email.id).join(', '), notes: String(open.notes || '') + '\n' + note
  });
} else {
  mode = 'create';
  const nums = rows.map((r) => parseInt(String(r.ticket_id).replace(/\D/g, ''), 10)).filter((n) => !isNaN(n));
  ticket = {
    ticket_id: 'TKT-' + String((nums.length ? Math.max.apply(null, nums) : 0) + 1).padStart(3, '0'),
    created_at: email.received_at, updated_at: email.received_at,
    order_id: row.order_id, customer_email: String(email.from.email).toLowerCase(), email_ids: email.id,
    intent: row.intent, priority: row.sentiment === 'angry' ? 'High' : 'Medium', status: 'Open',
    summary: row.notes, notes: note
  };
}
return [{ json: { mode, ticket } }];

// Node: "Build audit row"  (n8n Code node, run once for each item)  [v1]
//
// Takes the row the classifier already built and fills in what v1 knows: the action,
// the reply, needs_human, the ticket id and the token estimate.

const d = $('Decide').first().json;
const row = Object.assign({}, d.row);

let ticketId = '';
let ticketMode = '';
try { const t = $('Plan ticket').first().json; ticketId = t.ticket.ticket_id; ticketMode = t.mode; } catch (e) { /* no ticket */ }

const prep = $('Prepare email').first().json;
row.action_taken = d.action;
row.order_found = d.order_found === null ? '' : (d.order_found ? 'TRUE' : 'FALSE');
row.needs_human = d.needs_human ? 'TRUE' : 'FALSE';
row.ticket_id = ticketId;
row.reply_draft = d.reply;
row.processed_at = new Date().toISOString();
row.tokens_in = (Number(row.tokens_in) || 0) + d.tokens_agent_in_est;
row.tokens_out = (Number(row.tokens_out) || 0) + d.tokens_agent_out_est;
row.latency_ms = Date.now() - (prep.started_at || Date.now());
row.notes = row.notes + (d.reasons.length ? ' | Needs human: ' + d.reasons.join(', ') : '') + (ticketMode ? ' | Ticket ' + ticketId + ' (' + ticketMode + ')' : '');
row.guard_flags = '';
row.facts_json = '';
row.trace_json = JSON.stringify({ steps: [
  { name: 'classify', model: prep.model, tokens_in: JSON.parse(row.trace_json || '{"steps":[{}]}').steps[0].tokens_in },
  { name: 'agent', tools: d.tools_used, tokens_in_est: d.tokens_agent_in_est, tokens_out_est: d.tokens_agent_out_est, tokens_are_estimates: true },
  { name: 'ticket', mode: ticketMode || 'none', id: ticketId }
] });

return { json: { row } };
